#!/bin/bash
# ECS User Data — runs ONCE on first boot of the instance.
# Sets up Docker, creates a systemd service that pulls from CR and
# runs the app on every boot (including after restarts).
#
# DO NOT edit this file directly.
# Run: make generate-user-data → produces scripts/user-data.sh with real values.
# Then paste scripts/user-data.sh into Byteplus Console → ECS → User Data.

set -euo pipefail

# ── Injected by generate-user-data.sh ────────────────────────────────────────
CR_REGISTRY="cr-mittul-ap-southeast-3.cr.bytepluses.com"
CR_USERNAME="mittul.madaan@78638713"
CR_PASSWORD="Gannu@1994"
IMAGE="cr-mittul-ap-southeast-3.cr.bytepluses.com/mittul/lead-engine:latest"
APP_DIR="/opt/lead-engine"

# ── Env vars for the container (injected from .env.production) ────────────────
DATABASE_URL="postgresql://mittul:Gannu@1994@postgresf90f08626dca.rds-pg.ibytepluses.com/lead-pipeline"
LLM_MODEL="seed-2-0-pro-260328"
LLM_API_KEY="291e83aa-08bc-47ff-aca8-31e5807d027d"
LLM_PROVIDER="openai"
LLM_API_BASE="https://ark.ap-southeast.bytepluses.com/api/v3"
LLM_TIMEOUT_SECONDS="30"
OUTPUT_DIR="./output"
# ─────────────────────────────────────────────────────────────────────────────

echo "[1/5] Installing Docker..."
apt-get update -qq
apt-get install -y --no-install-recommends ca-certificates curl

install -m 0755 -d /etc/apt/keyrings
curl -fsSL https://download.docker.com/linux/ubuntu/gpg \
  -o /etc/apt/keyrings/docker.asc
chmod a+r /etc/apt/keyrings/docker.asc

echo \
  "deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/docker.asc] \
  https://download.docker.com/linux/ubuntu \
  $(. /etc/os-release && echo "$VERSION_CODENAME") stable" \
  | tee /etc/apt/sources.list.d/docker.list > /dev/null

apt-get update -qq
apt-get install -y docker-ce docker-ce-cli containerd.io
systemctl enable --now docker

echo "[2/5] Creating app directories..."
mkdir -p "$APP_DIR/output/runs"

echo "[3/5] Writing container env file to /etc/lead-engine.env ..."
cat > /etc/lead-engine.env << ENV
DATABASE_URL=$DATABASE_URL
LLM_MODEL=$LLM_MODEL
LLM_API_KEY=$LLM_API_KEY
LLM_PROVIDER=$LLM_PROVIDER
LLM_API_BASE=$LLM_API_BASE
LLM_TIMEOUT_SECONDS=$LLM_TIMEOUT_SECONDS
OUTPUT_DIR=$OUTPUT_DIR
ENV
chmod 600 /etc/lead-engine.env

echo "[4/5] Creating systemd service..."
cat > /etc/systemd/system/lead-engine.service << SERVICE
[Unit]
Description=Lead Generation Engine
After=docker.service network-online.target
Requires=docker.service

[Service]
Restart=always
RestartSec=5

# Authenticate to CR before pulling
ExecStartPre=/bin/bash -c 'echo "$CR_PASSWORD" | docker login $CR_REGISTRY -u $CR_USERNAME --password-stdin'
# Stop + remove old container if running
ExecStartPre=-/usr/bin/docker stop lead-engine
ExecStartPre=-/usr/bin/docker rm lead-engine
# Pull latest image from CR
ExecStartPre=/usr/bin/docker pull $IMAGE

ExecStart=/usr/bin/docker run --rm \\
  --name lead-engine \\
  -p 8080:8080 \\
  --env-file /etc/lead-engine.env \\
  -v $APP_DIR/output/runs:/app/output/runs \\
  $IMAGE

ExecStop=/usr/bin/docker stop lead-engine

[Install]
WantedBy=multi-user.target
SERVICE

# Embed CR credentials for the systemd service
mkdir -p /etc/systemd/system/lead-engine.service.d
cat > /etc/systemd/system/lead-engine.service.d/cr-auth.conf << CONF
[Service]
Environment="CR_REGISTRY=$CR_REGISTRY"
Environment="CR_USERNAME=$CR_USERNAME"
Environment="CR_PASSWORD=$CR_PASSWORD"
Environment="IMAGE=$IMAGE"
CONF
chmod 600 /etc/systemd/system/lead-engine.service.d/cr-auth.conf

echo "[5/5] Enabling and starting lead-engine service..."
systemctl daemon-reload
systemctl enable lead-engine
systemctl start lead-engine

echo "==> User data complete. App will be available on port 8080 shortly."
echo "    Check status: systemctl status lead-engine"
echo "    Check logs  : journalctl -u lead-engine -f"
